CREATE TYPE public.app_role AS ENUM ('tourist','leader','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100), phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'tourist'); RETURN NEW; END $$;
CREATE TRIGGER torino_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account();
CREATE TABLE public.leader_profiles (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100), bio text NOT NULL DEFAULT '' CHECK(length(bio)<=4000), status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','suspended','revoked')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.leader_profiles TO anon,authenticated; GRANT UPDATE(display_name,bio) ON public.leader_profiles TO authenticated; GRANT ALL ON public.leader_profiles TO service_role;
ALTER TABLE public.leader_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY leader_public ON public.leader_profiles FOR SELECT TO anon,authenticated USING(status='approved');
CREATE POLICY leader_private ON public.leader_profiles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY leader_edit ON public.leader_profiles FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.apply_as_leader() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; INSERT INTO public.leader_profiles(user_id,display_name) SELECT id,display_name FROM public.profiles WHERE id=auth.uid() ON CONFLICT DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'leader') ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.apply_as_leader() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.apply_as_leader() TO authenticated;
CREATE FUNCTION public.review_leader(target uuid,decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF decision NOT IN('approved','suspended','revoked') THEN RAISE EXCEPTION 'Invalid status'; END IF; UPDATE public.leader_profiles SET status=decision WHERE user_id=target; END $$;
REVOKE ALL ON FUNCTION public.review_leader(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_leader(uuid,text) TO authenticated;
CREATE TABLE public.tours (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), leader_id uuid NOT NULL REFERENCES public.leader_profiles(user_id), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160), destination text NOT NULL CHECK(length(destination) BETWEEN 1 AND 160), category text NOT NULL DEFAULT 'طبیعت‌گردی' CHECK(length(category)<=80), description text NOT NULL DEFAULT '' CHECK(length(description)<=6000), rules text NOT NULL DEFAULT '' CHECK(length(rules)<=6000), required_documents text NOT NULL DEFAULT '' CHECK(length(required_documents)<=2000), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, capacity integer NOT NULL CHECK(capacity>0), price bigint NOT NULL CHECK(price>=0), published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
GRANT SELECT ON public.tours TO anon,authenticated; GRANT INSERT,UPDATE ON public.tours TO authenticated; GRANT ALL ON public.tours TO service_role;
ALTER TABLE public.tours ENABLE ROW LEVEL SECURITY;
CREATE POLICY tours_public ON public.tours FOR SELECT TO anon,authenticated USING(published AND EXISTS(SELECT 1 FROM public.leader_profiles l WHERE l.user_id=leader_id AND l.status='approved'));
CREATE POLICY tours_private ON public.tours FOR SELECT TO authenticated USING(leader_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY tours_create ON public.tours FOR INSERT TO authenticated WITH CHECK(leader_id=auth.uid() AND EXISTS(SELECT 1 FROM public.leader_profiles l WHERE l.user_id=auth.uid() AND l.status='approved'));
CREATE POLICY tours_edit ON public.tours FOR UPDATE TO authenticated USING(leader_id=auth.uid() AND EXISTS(SELECT 1 FROM public.leader_profiles l WHERE l.user_id=auth.uid() AND l.status='approved')) WITH CHECK(leader_id=auth.uid() AND EXISTS(SELECT 1 FROM public.leader_profiles l WHERE l.user_id=auth.uid() AND l.status='approved'));
CREATE TABLE public.bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tour_id uuid NOT NULL REFERENCES public.tours(id), tourist_id uuid NOT NULL REFERENCES public.profiles(id), full_name text NOT NULL CHECK(length(full_name) BETWEEN 1 AND 100), phone text NOT NULL CHECK(length(phone) BETWEEN 1 AND 30), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000), document_paths text[] NOT NULL DEFAULT '{}', accepted_rules boolean NOT NULL CHECK(accepted_rules), status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','paid')), agreed_price bigint NOT NULL CHECK(agreed_price>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tour_id,tourist_id));
GRANT SELECT ON public.bookings TO authenticated; GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY booking_read ON public.bookings FOR SELECT TO authenticated USING(tourist_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.tours t WHERE t.id=tour_id AND t.leader_id=auth.uid()));
CREATE POLICY booked_tour_read ON public.tours FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.bookings b WHERE b.tour_id=id AND b.tourist_id=auth.uid()));
CREATE FUNCTION public.request_booking(trip uuid,passenger_name text,contact text,remarks text,documents text[],accept_rules boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tours; result uuid; p text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO t FROM public.tours WHERE id=trip FOR UPDATE; IF t.id IS NULL OR NOT t.published OR t.starts_at<=now() OR NOT EXISTS(SELECT 1 FROM public.leader_profiles WHERE user_id=t.leader_id AND status='approved') THEN RAISE EXCEPTION 'Trip unavailable'; END IF; IF t.leader_id=auth.uid() THEN RAISE EXCEPTION 'Cannot book own trip'; END IF; IF NOT coalesce(accept_rules,false) THEN RAISE EXCEPTION 'Accept trip rules'; END IF; IF length(trim(passenger_name)) NOT BETWEEN 1 AND 100 OR length(trim(contact)) NOT BETWEEN 1 AND 30 OR length(remarks)>2000 OR cardinality(documents)>10 THEN RAISE EXCEPTION 'Invalid passenger details'; END IF; IF t.required_documents<>'' AND cardinality(documents)=0 THEN RAISE EXCEPTION 'Documents required'; END IF; FOREACH p IN ARRAY documents LOOP IF split_part(p,'/',1)<>auth.uid()::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='booking-documents' AND name=p) THEN RAISE EXCEPTION 'Invalid document'; END IF; END LOOP; INSERT INTO public.bookings(tour_id,tourist_id,full_name,phone,notes,document_paths,accepted_rules,agreed_price) VALUES(trip,auth.uid(),trim(passenger_name),trim(contact),remarks,documents,true,t.price) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.request_booking(uuid,text,text,text,text[],boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.request_booking(uuid,text,text,text,text[],boolean) TO authenticated;
CREATE FUNCTION public.decide_booking(request_id uuid,decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings; t public.tours; BEGIN SELECT * INTO b FROM public.bookings WHERE id=request_id; SELECT * INTO t FROM public.tours WHERE id=b.tour_id FOR UPDATE; IF t.leader_id IS DISTINCT FROM auth.uid() OR NOT EXISTS(SELECT 1 FROM public.leader_profiles WHERE user_id=auth.uid() AND status='approved') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF b.status<>'pending' OR decision NOT IN('approved','rejected') OR t.starts_at<=now() THEN RAISE EXCEPTION 'Invalid decision'; END IF; IF decision='approved' AND (SELECT count(*) FROM public.bookings WHERE tour_id=t.id AND status IN('approved','paid'))>=t.capacity THEN RAISE EXCEPTION 'Trip full'; END IF; UPDATE public.bookings SET status=decision WHERE id=request_id AND status='pending'; END $$;
REVOKE ALL ON FUNCTION public.decide_booking(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.decide_booking(uuid,text) TO authenticated;
CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES public.bookings(id), tourist_id uuid NOT NULL REFERENCES public.profiles(id), leader_id uuid NOT NULL REFERENCES public.leader_profiles(user_id), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '' CHECK(length(comment)<=2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reviews TO anon,authenticated; GRANT ALL ON public.reviews TO service_role;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviews_public ON public.reviews FOR SELECT TO anon,authenticated USING(true);
CREATE FUNCTION public.rate_trip(request_id uuid,stars integer,message text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings; t public.tours; BEGIN SELECT * INTO b FROM public.bookings WHERE id=request_id; SELECT * INTO t FROM public.tours WHERE id=b.tour_id; IF b.tourist_id IS DISTINCT FROM auth.uid() OR b.status<>'paid' OR t.ends_at>now() THEN RAISE EXCEPTION 'Rating requires a completed paid trip'; END IF; INSERT INTO public.reviews(booking_id,tourist_id,leader_id,rating,comment) VALUES(b.id,auth.uid(),t.leader_id,stars,message); END $$;
REVOKE ALL ON FUNCTION public.rate_trip(uuid,integer,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.rate_trip(uuid,integer,text) TO authenticated;
CREATE TABLE public.leader_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), leader_id uuid NOT NULL REFERENCES public.leader_profiles(user_id), tour_id uuid REFERENCES public.tours(id), path text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN('image','video')), caption text NOT NULL DEFAULT '' CHECK(length(caption)<=300), visible boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.leader_media TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.leader_media TO authenticated; GRANT ALL ON public.leader_media TO service_role;
ALTER TABLE public.leader_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY media_public ON public.leader_media FOR SELECT TO anon,authenticated USING(visible AND EXISTS(SELECT 1 FROM public.leader_profiles WHERE user_id=leader_id AND status='approved'));
CREATE POLICY media_own ON public.leader_media FOR SELECT TO authenticated USING(leader_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY media_create ON public.leader_media FOR INSERT TO authenticated WITH CHECK(leader_id=auth.uid() AND split_part(path,'/',1)=auth.uid()::text AND (tour_id IS NULL OR EXISTS(SELECT 1 FROM public.tours t WHERE t.id=tour_id AND t.leader_id=auth.uid() AND t.ends_at<=now())));
CREATE POLICY media_update ON public.leader_media FOR UPDATE TO authenticated USING(leader_id=auth.uid()) WITH CHECK(leader_id=auth.uid() AND split_part(path,'/',1)=auth.uid()::text AND (tour_id IS NULL OR EXISTS(SELECT 1 FROM public.tours t WHERE t.id=tour_id AND t.leader_id=auth.uid() AND t.ends_at<=now())));
CREATE POLICY media_delete ON public.leader_media FOR DELETE TO authenticated USING(leader_id=auth.uid());
CREATE TABLE public.favorites (tourist_id uuid NOT NULL REFERENCES public.profiles(id),tour_id uuid NOT NULL REFERENCES public.tours(id),PRIMARY KEY(tourist_id,tour_id));
GRANT SELECT,INSERT,DELETE ON public.favorites TO authenticated; GRANT ALL ON public.favorites TO service_role;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY favorites_own ON public.favorites FOR ALL TO authenticated USING(tourist_id=auth.uid()) WITH CHECK(tourist_id=auth.uid());
CREATE POLICY document_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='booking-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY document_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='booking-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.bookings b JOIN public.tours t ON t.id=b.tour_id WHERE name=ANY(b.document_paths) AND t.leader_id=auth.uid())));
CREATE POLICY portfolio_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='leader-media' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'leader'));
CREATE POLICY portfolio_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='leader-media' AND (EXISTS(SELECT 1 FROM public.leader_media m WHERE m.path=name AND m.visible AND EXISTS(SELECT 1 FROM public.leader_profiles l WHERE l.user_id=m.leader_id AND l.status='approved')) OR (storage.foldername(name))[1]=auth.uid()::text));
CREATE INDEX bookings_trip_idx ON public.bookings(tour_id); CREATE INDEX tours_leader_idx ON public.tours(leader_id);